316	// ids.ts
317	import { randomBytes } from 'node:crypto';
318	export const entryId = (sessionId: string, index: number) => `${sessionId}:${index}`;
319	export const newId = (prefix: string) => `${prefix}_${randomBytes(6).toString('hex')}`;
