653	export interface TtsProvider { name: string; synthesize(text: string, voice: string): Promise<{ pcm: Buffer; sampleRate: number }> }
654	export class TtsQuotaError extends Error {}
655	export function createGeminiTts(keys: string[], o?: { models?: string[]; fetchImpl?: typeof fetch }): TtsProvider
